SELECT CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, AVG(o.shipping_fee) AS avg_shipping_fee, ROUND(AVG(o.amount), 2) AS avg_amount FROM orders o INNER JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END;
